UPDATE companies SET description='AES Foods operates from Newark, Delaware, and has been active since 2007. The company describes itself as a distributor and retailer of fine meats and products, with a focus on bringing Farmers Choice Sausages to the U.S. market. Ownership details and founders are not disclosed.

The product catalog centers on African and Kenyan food items. AES Foods imports and sells Paddy''s Farmers Choice Sausages in pork, beef, and chicken varieties, alongside Kenyan black teas, green teas, herbal teas, flavored teas, and coffee. The range extends to spices, herbs, seasonings, tomato and hot sauces, jams, margarine, non-GMO white cornmeal (Ugali Poa), wheat flour, beans, grains, lentils, and fresh meats including beef, goat, lamb, and seafood. Brands carried include KETEPA teas, Blue Band margarine, and Super Sela Basmati rice.

The company sells directly to consumers through its e-commerce site, offering retail packs and multi-pack promotions.

AES Foods emphasizes the distinctive taste of its Farmers Choice Sausages, noting that the products command a slightly higher cost but are "worth every penny." The business was built on the goal of delivering that specific sausage profile to the U.S. market.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Food importation", "Distribution", "Retail e-commerce"], "industries": [], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Distinctive taste of Farmers Choice Sausages", "Direct importer of Kenyan food products", "Free spice promotions with sausage packs", "Non-GMO cornmeal and organic, antibiotic-free chicken sausages"], "facts_used": ["Company name AES FOODS -> db", "Headquarters Newark, Delaware -> db", "Founded/active since 2007 -> db", "Business type: distributor and retailer -> /", "Product lines: Paddy''s Farmers Choice Sausages, Kenyan teas, coffees, spices, flours, meats -> /", "Brands: KETEPA, Blue Band, Ugali Poa, Super Sela Basmati -> /", "Claims: distinctive taste, worth every penny, non-GMO, organic antibiotic-free -> /"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "Welcome to AES Foods, distributer and retailer of fine meats and products", "founded_year": "2007", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='aes-foods' AND approved AND profile IS NULL;
UPDATE companies SET description='AG Interior Designs was founded in 2013 in Las Vegas, Nevada. The company operates two dedicated manufacturing floors in its hometown, producing custom furniture, drapery, and automated window treatments for high-end residential and commercial projects across the western United States.

The shop specializes in handcrafted custom furniture, luxury drapery, motorized window coverings, and reupholstery services. Its output spans complete hardware solutions for window treatments and bespoke furnishings, all fabricated in-house. The facility serves designers and direct clients with projects ranging from single-room residential installations to large-scale hospitality and casino fit-outs.

Primary markets include luxury residential, hospitality (five-star resorts and casinos), and exclusive commercial spaces. The company works with interior designers and high-end clients throughout Nevada, California, Arizona, Utah, and Colorado, delivering made-in-the-USA products for both new construction and renovation.

AG Interior Designs emphasizes custom craftsmanship built to each client''s vision, sourcing premium fabrics, woods, and hardware. A stated differentiator is smart-home integration, particularly motorized drapery and automated window coverings, paired with a reputation for meticulous attention to detail across all project phases.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture manufacturing", "Drapery fabrication", "Motorized window treatment installation", "Automated window covering integration", "Reupholstery services", "Complete hardware solutions for window treatments", "Luxury upholstery services"], "industries": ["Luxury residential", "Hospitality", "Commercial interiors", "Casino and resort fit-out"], "materials": ["Fabrics", "Woods", "Hardware"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Two dedicated manufacturing floors in Las Vegas", "In-house fabrication of custom furniture, drapery, and motorized window treatments", "Smart-home integration for automated window coverings", "Premium material sourcing: fabrics, woods, and hardware", "Service across Nevada, California, Arizona, Utah, and Colorado"], "facts_used": ["Founded in 2013 -> /about-us", "Headquartered in Las Vegas, NV with two manufacturing floors -> /about-us", "Specializes in handcrafted custom furniture, high-end drapery, motorized window treatments, luxury upholstery -> /about-us", "Reupholstery services offered -> db capabilities", "Complete hardware solutions -> db products", "Serves luxury homes, five-star resorts, world-class casinos, exclusive commercial spaces -> /about-us", "Service areas: Nevada, California, Arizona, Utah, Colorado -> /about-us", "Custom craftsmanship, luxury-quality materials, smart home integration stated as differentiators -> /about-us", "Products proudly made in USA -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "AG Interior Designs has grown into a leading custom