any", "makes_products": "no", "type_evidence": "ALL SKY ENERGY SPECIALIZES IN SOLAR PV INSTALLATIONS & EV CHARGING STATIONS", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='all-sky-energy-llc' AND approved AND profile IS NULL;
